from typing import List


def powerset(arr: List) -> List[List]:
    if arr:
        first, *rest = arr  # Python 3 just like car and cdr (in this case anyway..)
        rest_subsets = powerset(rest)
        return [[first] + subset for subset in rest_subsets]
    else:
        return [[]]
